// Splits the comma-separated channel ID list from config into one item per
// channel so the channel loop below can fetch each one's RSS feed in turn.
const config = $('Configure Scan Parameters').first().json;
const ids = String(config.competitorChannelIds || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

return ids.map((channelId) => ({ json: { channelId } }));

// Parses one channel's YouTube Atom RSS feed into candidate videos. A dead,
// private, or rate-limited channel just yields zero videos here (thanks to
// onError=continueRegularOutput on the fetch above) instead of throwing, so
// one bad channel ID never kills the whole run.
const config = $('Configure Scan Parameters').first().json;
const channelId = $('Batch Process Channels').first().json.channelId;

const item = $input.first().json;
const body = typeof item.data === 'string' ? item.data : (item.body || '');
const entries = String(body).match(/<entry>[\s\S]*?<\/entry>/g) || [];

const results = [];
for (const entry of entries) {
  const idMatch = entry.match(/<yt:videoId>([\s\S]*?)<\/yt:videoId>/);
  const titleMatch = entry.match(/<title>([\s\S]*?)<\/title>/);
  const publishedMatch = entry.match(/<published>([\s\S]*?)<\/published>/);
  const linkMatch = entry.match(/<link[^>]*href="([^"]*)"/);
  if (!idMatch || !titleMatch) continue;

  const videoId = idMatch[1].trim();
  results.push({
    channelId,
    videoId,
    title: titleMatch[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim(),
    publishedAt: publishedMatch ? publishedMatch[1].trim() : '',
    link: linkMatch ? linkMatch[1] : ('https://www.youtube.com/watch?v=' + videoId),
  });
}

return results.slice(0, config.maxVideosPerChannel || 5).map((r) => ({ json: r }));

// Collects every video parsed across all channel-loop iterations. Once a
// SplitInBatches loop has finished, referencing a node that ran inside it
// with .all() returns items from every iteration, not just the last one.
const videos = $('Parse Videos from RSS').all().map((i) => i.json);
return videos.map((v) => ({ json: v }));

// Filters out videos already logged as seen, applies the optional manual
// test switch, and caps the batch so the AI idea-generation loop stays
// bounded and cheap.
const config = $('Configure Scan Parameters').first().json;

let seenRows = [];
try {
  seenRows = $('Read Seen Video IDs from Sheet').all().map((r) => r.json);
} catch (e) {
  seenRows = [];
}
const seenIds = new Set(seenRows.map((r) => String(r.videoId || r.VideoId || '')).filter(Boolean));

let candidates = $input.all().map((i) => i.json).filter((v) => v.videoId && !seenIds.has(v.videoId));

// TEMPORARY TEST SWITCH — set config.FORCE_CHANGE_FOR back to '' before submitting.
// Lets the first run exercise the AI idea-generation + sheet-write path even
// when live competitor channels have nothing new.
if (config.FORCE_CHANGE_FOR) {
  candidates = [{
    channelId: 'manual-test',
    videoId: 'manual-test-' + Date.now(),
    title: config.FORCE_CHANGE_FOR,
    publishedAt: new Date().toISOString(),
    link: '',
  }, ...candidates];
}

const limited = candidates.slice(0, config.maxCandidatesPerRun || 10);

return [{ json: { hasChanges: limited.length > 0, candidateCount: limited.length, candidates: limited } }];

// Split the batched candidate list into one item per video for the loop.
const data = $input.first().json;
return (data.candidates || []).map((c) => ({ json: c }));

