// Defensively extracts the JSON contract from the LLM chain output, whatever
// shape the provider returns it in. On parse failure, surfaces a mid-range
// score instead of silently hiding a real result.
function extractText(output) {
  if (typeof output === 'string') return output;
  if (!output || typeof output !== 'object') return '';
  if (typeof output.text === 'string') return output.text;
  if (typeof output.output === 'string') return output.output;
  if (output.message && typeof output.message.content === 'string') return output.message.content;
  if (Array.isArray(output.content)) {
    const parts = output.content.map((p) => (p && p.text) || '').join('');
    if (parts) return parts;
  }
  if (Array.isArray(output.candidates)) {
    const parts = output.candidates[0] && output.candidates[0].content && output.candidates[0].content.parts;
    if (Array.isArray(parts)) return parts.map((p) => p.text || '').join('');
  }
  return JSON.stringify(output);
}

const item = $input.first().json;
const candidate = $('Batch Process Candidates').first().json;
const rawOutput = item.text !== undefined ? item.text : (item.output !== undefined ? item.output : item);
const text = extractText(rawOutput);
const cleaned = String(text).replace(/```json|```/g, '').trim();
const match = cleaned.match(/\{[\s\S]*\}/);

let parsed = null;
try {
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch (e) {
  parsed = null;
}

let result;
if (parsed && typeof parsed.opportunityScore === 'number') {
  result = {
    channelId: candidate.channelId,
    videoId: candidate.videoId,
    competitorTitle: candidate.title,
    link: candidate.link,
    ideaTitles: Array.isArray(parsed.ideaTitles) ? parsed.ideaTitles.join(' | ') : String(parsed.ideaTitles || ''),
    opportunityScore: parsed.opportunityScore,
    differentiation: parsed.differentiation || '',
    contentFormat: parsed.contentFormat || '',
    reasoning: parsed.reasoning || '',
  };
} else {
  result = {
    channelId: candidate.channelId,
    videoId: candidate.videoId,
    competitorTitle: candidate.title,
    link: candidate.link,
    ideaTitles: '',
    opportunityScore: 5,
    differentiation: '',
    contentFormat: 'unknown',
    reasoning: 'Could not parse AI response for this video; flagged for manual review.',
  };
}

return [{ json: result }];

// Shapes a minimal record for the Seen Videos sheet — keeps that sheet's
// columns limited to what dedup actually needs, instead of inheriting every
// AI-scoring field from the idea record.
const item = $input.first().json;
return [{
  json: {
    videoId: item.videoId,
    channelId: item.channelId,
    title: item.competitorTitle,
    seenAt: new Date().toISOString(),
  },
}];

// Summarizes what this run found for the notification decision below —
// reading back from Save Idea To Sheet (rather than re-deriving it)
// guarantees the digest matches exactly what was written to the sheet.
let saved = [];
try {
  saved = $('Append Idea to Spreadsheet').all().map((r) => r.json);
} catch (e) {
  saved = [];
}

return [{
  json: {
    hasIdeas: saved.length > 0,
    ideaCount: saved.length,
    ideas: saved,
  },
}];

const data = $input.first().json;
const lines = data.ideas.map((idea, idx) => {
  const firstTitle = idea.ideaTitles ? idea.ideaTitles.split(' | ')[0] : idea.competitorTitle;
  return (idx + 1) + '. ' + firstTitle + '\n   Format: ' + (idea.contentFormat || 'n/a') + ' | Score: ' + idea.opportunityScore + '\n   Why: ' + (idea.reasoning || '') + '\n   Inspired by: ' + (idea.link || '');
}).join('\n\n');

return [{
  json: {
    subject: data.ideaCount + ' new YouTube content idea' + (data.ideaCount === 1 ? '' : 's') + ' from competitors',
    body: 'Here are this run\'s content ideas, generated from competitor videos:\n\n' + lines,
  },
}];
